from django.contrib import admin

from audit.admin import ReadOnlyModelAdmin, ReadOnlyTabularInline
from team.models import Commission


class CommissionInline(ReadOnlyTabularInline):
    """Commissions generated by one pay-in (shown on the PayIn page)."""

    model = Commission
    fk_name = 'payin'
    fields = ['level', 'beneficiary', 'rate', 'base_amount', 'amount', 'created_at']
    ordering = ['level']


@admin.register(Commission)
class CommissionAdmin(ReadOnlyModelAdmin):
    """View-only: commissions are written solely by the pay-in confirmation."""

    list_display = ['id', 'created_at', 'beneficiary', 'level', 'rate', 'base_amount', 'amount', 'source_user', 'payin', 'order_reference']
    list_filter = ['level', 'created_at']
    search_fields = [
        'beneficiary__mobile_number', 'beneficiary__name', 'beneficiary__referral_code',
        'source_user__mobile_number', 'source_user__name',
        'payin__order__reference', 'payin__utr',
    ]
    list_select_related = ['beneficiary', 'source_user', 'payin__order']
    date_hierarchy = 'created_at'
    ordering = ['-created_at', '-id']

    @admin.display(description='Order', ordering='payin__order__reference')
    def order_reference(self, obj):
        return obj.payin.order.reference
